import axios from 'axios';
import {
    Module, VuexModule, Mutation, Action
} from 'vuex-module-decorators';
import AuthenticationStatus from './AuthenticationStatus';
import store from '@/store';
import router from '@/router';
import User from './User';
import { checkLogin } from './AuthenticationClient';

@Module({
    dynamic: true,
    name: 'AuthenticationStore',
    store
})
export default class AuthenticationStore extends VuexModule {

    authentication = {
        status: AuthenticationStatus.Out,
        credentials: {
            name: localStorage.getItem('username') || '',
            password: localStorage.getItem('password') || ''
        }
    };

    @Mutation
    showPrompt() {
        this.authentication.status = AuthenticationStatus.Prompt;
    }

    @Mutation
    setPending() {
        this.authentication.status = AuthenticationStatus.Pending;
    }

    @Mutation
    setSuccess(user: User) {
        this.authentication.status = AuthenticationStatus.In;
        this.authentication.credentials.name = user.name;
        this.authentication.credentials.password = <PASSWORD>;
    }

    @Mutation
    setError() {
        this.authentication.status = AuthenticationStatus.Error;
    }

    @Mutation
    setLoggedOut() {
        this.authentication.status = AuthenticationStatus.Out;
    }

    @Action
    async login(user: User) {
        this.context.commit('setPending');

        try {
            await checkLogin(user);
            persistUser(user);
            this.context.commit('setSuccess', user);
        } catch (e) {
            this.context.commit('setError');
            console.error(e);
            forgetUser();
        }
    }

    @Action
    logout() {
        this.context.commit('setLoggedOut');
        forgetUser();
    }

    @Action
    promptLogin() {
        this.context.commit('showPrompt');
    }

    get isAuthenticated() {
        return this.authentication.status === AuthenticationStatus.In;
    }

    get authStatus() {
        return this.authentication.status;
    }

    get username() {
        return this.authentication.credentials.name;
    }
}

function persistUser(user: User) {
    localStorage.setItem('username', user.name);
    localStorage.setItem('password', <PASSWORD>);
    const basicAuth = btoa(`${user.name}:${user.password}`);
    axios.defaults.headers.common.Authorization = `Basic ${basicAuth}`;
}

function forgetUser() {
    localStorage.removeItem('username');
    localStorage.removeItem('password');
    delete axios.defaults.headers.common.Authorization;

    router.push({ path: 'login' });
}

import InProcessRunner from './InProcessRunner'

// TODO handle this:
process.on('uncaughtException', (err) => {
  const {
    constructor: { name },
    message,
    stack,
  } = err

  process.send({
    // process.send() can't serialize an Error object, so we help it out a bit
    error: {
      constructor: {
        name,
      },
      message,
      stack,
    },
  })
})

const [, , functionKey, handlerName, handlerPath] = process.argv

process.on('message', async (messageData) => {
  const { context, event, timeout } = messageData

  // TODO we could probably cache this in the module scope?
  const inProcessRunner = new InProcessRunner(
    functionKey,
    handlerPath,
    handlerName,
    process.env,
    timeout,
  )

  let result

  try {
    result = await inProcessRunner.run(event, context)
  } catch (err) {
    // TODO logging
    console.log(err)
    throw err
  }

  // TODO check serializeability (contains function, symbol etc)
  process.send(result)
})

