import { init, SDK } from 'dc-extensions-sdk'
import { useState, useEffect } from 'react'

interface FieldModel {}

interface Parameters {
  instance: {}
  installation: {}
}

export function useExtension() {
  const [sdk, setSDK] = useState<SDK>()
  const [ready, setFetched] = useState<boolean>(false)
  const [initialData, setData] = useState<any>(false)
  const [required, setRequired] = useState<any>(false)

  async function initialize() {
    try {
      const sdk = await init<FieldModel, Parameters>({
        debug: process.env.NODE_ENV !== 'production',
      })
      setSDK(sdk)
    } catch (e) {
      console.error('Extension failed to connect to DC')
    }
  }

  useEffect(() => {
    if (!sdk) return

    async function fetchInitialData() {
      try {
        const data = await sdk?.field.getValue()
        const required = !(await sdk?.field.isValid(null))
        setData(data)
        setRequired(required)
      } catch (e) {
      } finally {
        setFetched(true)
      }
    }

    fetchInitialData()
  }, [sdk])

  useEffect(() => {
    initialize()
  }, [])

  return {
    sdk,
    ready,
    required,
    initialData,
  }
}

